#ifndef FAST_VECTOR_MATH_H
#define FAST_VECTOR_MATH_H

#include <godot_cpp/classes/ref_counted.hpp>
#include <godot_cpp/variant/vector3.hpp>
#include <godot_cpp/variant/packed_vector3_array.hpp>
#include <godot_cpp/variant/array.hpp>

namespace godot {

class FastVectorMath : public RefCounted {
	GDCLASS(FastVectorMath, RefCounted);

protected:
	static void _bind_methods();

public:
	FastVectorMath();
	~FastVectorMath();

	static float dot_product(const Vector3 &p_a, const Vector3 &p_b);
	static Vector3 cross_product(const Vector3 &p_a, const Vector3 &p_b);
	static Array compute_centroid_and_bounds(const PackedVector3Array &p_points);
	static float ray_sphere_intersection(const Vector3 &p_origin, const Vector3 &p_dir, const Vector3 &p_sphere_center, float p_radius);
};

} // namespace godot

#endif // FAST_VECTOR_MATH_H

#include "fast_vector_math.h"
#include <godot_cpp/core/class_db.hpp>
#include <cmath>

namespace godot {

FastVectorMath::FastVectorMath() {}
FastVectorMath::~FastVectorMath() {}

float FastVectorMath::dot_product(const Vector3 &p_a, const Vector3 &p_b) {
	return p_a.dot(p_b);
}

Vector3 FastVectorMath::cross_product(const Vector3 &p_a, const Vector3 &p_b) {
	return p_a.cross(p_b);
}

Array FastVectorMath::compute_centroid_and_bounds(const PackedVector3Array &p_points) {
	Vector3 centroid(0, 0, 0);
	Vector3 min_bounds(0, 0, 0);
	Vector3 max_bounds(0, 0, 0);
	int64_t size = p_points.size();

	if (size > 0) {
		centroid = p_points[0];
		min_bounds = p_points[0];
		max_bounds = p_points[0];

		for (int64_t i = 1; i < size; ++i) {
			Vector3 p = p_points[i];
			centroid += p;
			if (p.x < min_bounds.x) min_bounds.x = p.x;
			if (p.y < min_bounds.y) min_bounds.y = p.y;
			if (p.z < min_bounds.z) min_bounds.z = p.z;
			if (p.x > max_bounds.x) max_bounds.x = p.x;
			if (p.y > max_bounds.y) max_bounds.y = p.y;
			if (p.z > max_bounds.z) max_bounds.z = p.z;
		}
		centroid /= static_cast<double>(size);
	}

	Array result;
	result.resize(3);
	result[0] = centroid;
	result[1] = min_bounds;
	result[2] = max_bounds;
	return result;
}

float FastVectorMath::ray_sphere_intersection(const Vector3 &p_origin, const Vector3 &p_dir, const Vector3 &p_sphere_center, float p_radius) {
	Vector3 oc = p_origin - p_sphere_center;
	float a = p_dir.dot(p_dir);
	if (a < 1e-8f) {
		return -1.0f;
	}
	float half_b = p_dir.dot(oc);
	float c = oc.dot(oc) - p_radius * p_radius;
	float discriminant = half_b * half_b - a * c;

	if (discriminant < 0.0f) {
		return -1.0f;
	}

	float sqrtd = std::sqrt(discriminant);
	float t1 = (-half_b - sqrtd) / a;
	if (t1 > 0.0f) {
		return t1;
	}
	float t2 = (-half_b + sqrtd) / a;
	if (t2 > 0.0f) {
		return t2;
	}
	return -1.0f;
}

void FastVectorMath::_bind_methods() {
	ClassDB::bind_static_method("FastVectorMath", D_METHOD("dot_product", "a", "b"), &FastVectorMath::dot_product);
	ClassDB::bind_static_method("FastVectorMath", D_METHOD("cross_product", "a", "b"), &FastVectorMath::cross_product);
	ClassDB::bind_static_method("FastVectorMath", D_METHOD("compute_centroid_and_bounds", "points"), &FastVectorMath::compute_centroid_and_bounds);
	ClassDB::bind_static_method("FastVectorMath", D_METHOD("ray_sphere_intersection", "origin", "dir", "sphere_center", "radius"), &FastVectorMath::ray_sphere_intersection);
}

} // namespace godot

