func _init() -> void:
	# Instantiate FastVectorMath
	var fvm = ClassDB.instantiate("FastVectorMath")
	if not fvm:
		print("FAIL: Could not instantiate FastVectorMath")
		quit(1)
		return

	# Test 1: dot_product
	var dot_pass = false
	var a = Vector3(1.0, 2.0, 3.0)
	var b = Vector3(4.0, 5.0, 6.0)
	var dot_res = fvm.dot_product(a, b)
	# Expected: 1*4 + 2*5 + 3*6 = 4 + 10 + 18 = 32.0
	if abs(dot_res - 32.0) < 1e-5:
		print("PASS: dot_product")
		dot_pass = true
	else:
		print("FAIL: dot_product, expected 32.0, got ", dot_res)

	# Test 2: cross_product
	var cross_pass = false
	var cross_res = fvm.cross_product(a, b)
	# Expected: (2*6 - 3*5, 3*4 - 1*6, 1*5 - 2*4) = (-3, 6, -3)
	var expected_cross = Vector3(-3.0, 6.0, -3.0)
	if cross_res.distance_to(expected_cross) < 1e-5:
		print("PASS: cross_product")
		cross_pass = true
	else:
		print("FAIL: cross_product, expected ", expected_cross, " got ", cross_res)

	# Test 3: compute_centroid_and_bounds
	var centroid_pass = false
	var points = PackedVector3Array([
		Vector3(0.0, 0.0, 0.0),
		Vector3(2.0, 4.0, 6.0),
		Vector3(-1.0, 5.0, -3.0)
	])
	var cb_res = fvm.compute_centroid_and_bounds(points)
	# Centroid: (0 + 2 - 1)/3 = 1/3 = 0.333333
	#           (0 + 4 + 5)/3 = 9/3 = 3.0
	#           (0 + 6 - 3)/3 = 3/3 = 1.0
	# Min bounds: (-1.0, 0.0, -3.0)
	# Max bounds: (2.0, 5.0, 6.0)
	if cb_res.size() == 3:
		var centroid = cb_res[0]
		var min_b = cb_res[1]
		var max_b = cb_res[2]
		var expected_centroid = Vector3(1.0/3.0, 3.0, 1.0)
		var expected_min = Vector3(-1.0, 0.0, -3.0)
		var expected_max = Vector3(2.0, 5.0, 6.0)
		if centroid.distance_to(expected_centroid) < 1e-5 and \
		   min_b.distance_to(expected_min) < 1e-5 and \
		   max_b.distance_to(expected_max) < 1e-5:
			print("PASS: compute_centroid_and_bounds")
			centroid_pass = true
		else:
			print("FAIL: compute_centroid_and_bounds, got centroid=", centroid, " min=", min_b, " max=", max_b)
	else:
		print("FAIL: compute_centroid_and_bounds, expected array of size 3, got size ", cb_res.size())

	# Test 4: ray_sphere_intersection
	var ray_pass = false
	# Ray origin (0, 0, 5), direction (0, 0, -1), sphere at (0, 0, 0) with radius 2.0
	var origin = Vector3(0.0, 0.0, 5.0)
	var dir = Vector3(0.0, 0.0, -1.0)
	var sphere_center = Vector3(0.0, 0.0, 0.0)
	var radius = 2.0
	var dist = fvm.ray_sphere_intersection(origin, dir, sphere_center, radius)
	# Expected hit distance: 3.0 (from 5.0 to 2.0)
	# Also test a miss: ray pointing away: direction (0, 0, 1)
	var dist_miss = fvm.ray_sphere_intersection(origin, Vector3(0.0, 0.0, 1.0), sphere_center, radius)
	if abs(dist - 3.0) < 1e-5 and abs(dist_miss - (-1.0)) < 1e-5:
		print("PASS: ray_sphere_intersection")
		ray_pass = true
	else:
		print("FAIL: ray_sphere_intersection, got hit=", dist, " miss=", dist_miss)

	if dot_pass and cross_pass and centroid_pass and ray_pass:
		print("ALL TESTS PASSED")
		quit(0)
	else:
		print("SOME TESTS FAILED")
		quit(1)
